import React from 'react';
import { Link } from 'gatsby';
import Layout from '../../components/Layout';
import SEO from '../../components/SEO';
import { MESSAGING_PRODUCT_NAME } from '../../constants/brand';
import '../../styles/marketing.css';
import T from '../../i18n/LocalizedText';
import { usePageI18n } from '../../i18n';

export default function MessagingChannelsPage(pageContext) {
  const { locale, localePath } = usePageI18n(pageContext);

  return (
    <Layout locale={pageContext?.locale}>
      <SEO
        title={`Channels & status \u2014 ${MESSAGING_PRODUCT_NAME}`}
        description={`Which channels ${MESSAGING_PRODUCT_NAME} sends over today — SMS, email and WhatsApp, each connected to a provider account you already hold.`}
        pathname="/platform/roadmap/"
        softwareApp={false}
        breadcrumbs={[
          { name: 'Home', path: '/' },
          { name: MESSAGING_PRODUCT_NAME, path: '/platform/' },
          { name: 'Channels', path: '/platform/roadmap/' },
        ]} hrefLang={locale}
      />
      <div className="mk">
        <header className="mk-hero">
          <span className="mk-eyebrow"><T id="platform_roadmap.001">Channel status</T></span>
          <h1><T id="platform_roadmap.002">Three channels, one connection model</T></h1>
          <p className="mk-lead"><T id="platform_roadmap.003">
            SMS, email and WhatsApp each connect to an account you already hold. What differs between
            them is not whether they work &mdash; it is which channel-level capabilities they carry.
          </T></p>
        </header>

        <section className="mk-section">
          <h2><T id="platform_roadmap.004">SMS channel</T></h2>
          <p className="mk-section-lead"><T id="platform_roadmap.005">
            Self-service connections to your own CPaaS account, with routing, per-number pacing,
            opt-out suppression and segment accounting running on top.
          </T></p>
          <div className="mk-actions">
            <Link className="mk-btn mk-btn-secondary" to={localePath("/platform/sms/")}><T id="platform_roadmap.006">
              What the SMS channel does
            </T></Link>
            <Link className="mk-btn mk-btn-secondary" to={localePath("/integrations/")}><T id="platform_roadmap.007">
              Provider integrations
            </T></Link>
          </div>
        </section>

        <section className="mk-section">
          <h2><T id="platform_roadmap.008">Email and WhatsApp</T></h2>
          <p className="mk-section-lead"><T id="platform_roadmap.009">
            Both connect the same way as SMS: you pick a provider, link an account you already hold,
            and send from the console or the API.
          </T></p>
          <ul className="mk-list">
            <li><T id="platform_roadmap.010">The same console connection flow as SMS, and a documented send API per channel.</T></li>
            <li><T id="platform_roadmap.011">
              Delivery events normalized into the same statuses as SMS wherever the provider reports
              them back &mdash; Resend on email and Meta on WhatsApp today.
            </T></li>
            <li><T id="platform_roadmap.012">A metadata-only message log, so you keep the record without keeping the content.</T></li>
            <li><T id="platform_roadmap.013">Sent from your own provider account &mdash; your negotiated pricing and your invoice stay yours.</T></li>
          </ul>
        </section>

        <div className="mk-scope">
          <T id="platform_roadmap.014"><strong>Channel-level capabilities.</strong> Routing and automatic failover, per-number
          pacing and segment accounting are provided on the SMS channel. Delivery receipts are
          normalized wherever the provider reports delivery back, and opt-out suppression is applied
          to marketing sends on every channel &mdash; the automatic STOP-keyword path is the SMS one.
          On email and WhatsApp the layer covers connecting, sending and recording the outcome.
        </T></div>

        <section className="mk-section">
          <h2><T id="platform_roadmap.015">Other channels</T></h2>
          <p className="mk-section-lead"><T id="platform_roadmap.016">
            If you need something beyond SMS, email and WhatsApp, tell us what you are trying to do
            &mdash; the shape of the request genuinely affects which provider adapter we build next.
          </T></p>
          <div className="mk-actions">
            <Link className="mk-btn mk-btn-primary" to={localePath("/contact/")}><T id="platform_roadmap.017">
              Talk to us
            </T></Link>
            <Link className="mk-btn mk-btn-secondary" to={localePath("/platform/")}><T id="platform_roadmap.018">
              Back to {MESSAGING_PRODUCT_NAME}</T>
            </Link>
          </div>
        </section>
      </div>
    </Layout>
  );
}
